public sealed class Expedition {public long Id{get;set;}public long DestinationId{get;set;}public string State{get;set;}="Packing";public List<long> Members{get;set;}=[];public Dictionary<long,int> HomeCells{get;set;}=new();public Dictionary<string,int> Cargo{get;set;}=new();public List<long> Artifacts{get;set;}=[];public List<int> Route{get;set;}=[];public int RouteIndex{get;set;}public long NextAt{get;set;}public bool Returning{get;set;}public long SiteId{get;set;}public int FoodUsed{get;set;}public string Purpose{get;set;}="Expedition";}
