public sealed class RegionState
{
 public bool Initialized{get;set;}public bool Enabled{get;set;}public long NextId{get;set;}=1;public ulong RandomState{get;set;}public long ObservedDangerTick{get;set;}=-1;public long ObservedCraftTick{get;set;}=-1;public long LastDay{get;set;}public int Width{get;set;}=12;public int Height{get;set;}=12;public List<RegionTile> Tiles{get;set;}=[];public List<RegionFaction> Factions{get;set;}=[];public List<RegionalPerson> People{get;set;}=[];public List<RegionSite> Sites{get;set;}=[];public List<RegionArtifact> Artifacts{get;set;}=[];public List<ChronicleEntry> History{get;set;}=[];public List<RegionTreaty> Treaties{get;set;}=[];public List<Expedition> Parties{get;set;}=[];public List<RegionQuest> Quests{get;set;}=[];public List<VisitingTrader> Traders{get;set;}=[];public HashSet<long> Absent{get;set;}=[];public HashSet<long> RecordedDeaths{get;set;}=[];public long HomeSiteId{get;set;}public int ArtifactTransfers{get;set;}public int TradeTransactions{get;set;}
}
public sealed partial class World
{
 public RegionState Region{get;set;}=new();
 public bool IsAway(long id)=>Region.Absent.Contains(id)||Solar.Evacuees.Contains(id);
 public void EnsureRegion(){if(!Region.Initialized){Region.Initialized=true;Region.RandomState=(ulong)(uint)Seed+918733;Region.LastDay=Tick/TicksPerDay;EnsureInstitutions();}}
 public bool HasTreaty(long faction,string kind)=>Region.Treaties.Any(t=>t.Active&&t.FactionId==faction&&t.Kind==kind);
 public bool TradeAccess(long faction)=>Region.Factions.First(f=>f.Id==faction).Goodwill>-30||HasTreaty(faction,"Resource exchange");
 public void Chronicle(string kind,string text,long faction=0,long site=0,long artifact=0,long actor=0,long person=0,int year=0)
 {Region.History.Add(new(){Id=Region.NextId++,Year=year==0?100+(int)(Tick/TicksPerDay/30):year,Tick=Tick,Kind=kind,Text=text,FactionId=faction,SiteId=site,ArtifactId=artifact,LocalActorId=actor,PersonId=person});if(Region.History.Count>256)Region.History.RemoveAt(0);Record(text);}
 public void EnableRegion(Definitions d)
 {
  EnsureRegion();if(Region.Enabled)return;Region.Enabled=true;var random=new StableRandom((ulong)(uint)Seed+554877);
  for(int y=0;y<Region.Height;y++)for(int x=0;x<Region.Width;x++){int elevation=random.Next(100);Region.Tiles.Add(new(){X=x,Y=y,Height=elevation,Climate=random.Next(60)-10,Culture=1+x/2%6,Road=y==6||x==6,Terrain=elevation>80?"Highlands":elevation<18?"Wetland":"Steppe"});}
  string[] names=["Courts of the Vermilion Sun","Pale Collegia","Brass Pilgrimage","Garden Remnants","Salt Confederacies","Choir Below"];
  for(int i=0;i<names.Length;i++){var faction=new RegionFaction{Id=Region.NextId++,Name=names[i],Population=40+random.Next(60),Strength=8+random.Next(12),Goodwill=i==1?15:5+random.Next(16),Compatibility=random.Next(41)-20,Reserves=new(){{"meal",40},{"grain",60},{"brass",35},{"medicine",18},{"f-parts",20},{"wood",80},{"arrows",12}}};Region.Factions.Add(faction);var person=new RegionalPerson{Id=Region.NextId++,FactionId=faction.Id,Name=names[i].Split(' ')[0]+" Keeper "+(i+1),Born=65,Role="Envoy"};Region.People.Add(person);Region.People.Add(new(){Id=Region.NextId++,FactionId=faction.Id,Name=names[i].Split(' ')[0]+" Founder "+(i+1),Born=-20,Died=80,Role="Founder"});}
  Region.Tiles[6*Region.Width+6].Climate=(int)Physical.Weather;
  var home=new RegionSite{Id=Region.NextId++,Name="Observatory Refuge",Kind="Colony",X=6,Y=6,Discovered=true,HistoryTag="Restored refuge",Slot=0};Region.Sites.Add(home);Region.HomeSiteId=home.Id;
  (int X,int Y)[] towns=[(3,3),(8,6),(9,3),(3,9),(8,9),(10,10)];
  for(int i=0;i<6;i++){var f=Region.Factions[i];var site=new RegionSite{Id=Region.NextId++,Name=f.Name.Split(' ')[0]+" Haven",Kind="Town",X=towns[i].X,Y=towns[i].Y,FactionId=f.Id,Slot=i+1,HistoryTag="Trade settlement",Discovered=true};Region.Sites.Add(site);Chronicle("Founding",site.Name+" was founded by "+f.Name+".",f.Id,site.Id,person:Region.People.First(p=>p.FactionId==f.Id&&p.Role=="Founder").Id,year:1+random.Next(70));}
  string[] kinds=["University","Medical vault","Seed archive","Machine monastery","Necropolis","Observatory"];
  for(int i=0;i<6;i++){var owner=Region.Factions[(i+1)%6];var site=new RegionSite{Id=Region.NextId++,Name="Lost "+kinds[i],Kind=kinds[i],X=i==0?8:2+i,Y=i==0?4:1+i%3,FactionId=owner.Id,Slot=i+7,HistoryTag=i==0?"College evacuation":"Era collapse",Discovered=i==0};Region.Sites.Add(site);var artifact=new RegionArtifact{Id=Region.NextId++,Name=i==0?"Aster's memory-glass lens":kinds[i]+" manuscript",DefinitionId=i==0?"lens":"formula-folio",SiteId=site.Id,OwnerFactionId=owner.Id};Region.Artifacts.Add(artifact);owner.Claims.Add("artifact:"+artifact.Id);Chronicle("Evacuation",site.Name+" was abandoned; "+owner.Name+" retained a claim to "+artifact.Name+".",owner.Id,site.Id,artifact.Id,person:Region.People.First(p=>p.FactionId==owner.Id&&p.Role=="Envoy").Id,year:85+random.Next(10));}
  if(Find(Slice.Ruin.EngineId) is {} engine)Region.Artifacts.Add(new(){Id=Region.NextId++,Name="Refuge daylight engine",DefinitionId="relic",SiteId=home.Id,Custody="Colony",LocalEntityId=engine.Id,Anchored=true});
  Chronicle("Era","Ancient infrastructure was laid beneath the savannas; later cultural regions inherited its ruins.",year:-8000);Chronicle("Era","The long twilight fragmented the old colleges into the six present regional factions.",year:-1200);
  var lost=Region.Artifacts.First(a=>a.Name.StartsWith("Aster",StringComparison.Ordinal));Region.Quests.Add(new(){Id=Region.NextId++,Name="Return Aster's lens",Kind="Recovery",FactionId=lost.OwnerFactionId,SiteId=lost.SiteId,ArtifactId=lost.Id,Reward=new(){{"medicine",3},{"brass",5}}});
  Region.Quests.Add(new(){Id=Region.NextId++,Name="Food for a refuge",Kind="Aid",FactionId=Region.Factions[3].Id,SiteId=Region.Sites.First(s=>s.Kind=="Town"&&s.FactionId==Region.Factions[3].Id).Id,Reward=new(){{"f-parts",2}}});Region.Quests.Add(new(){Id=Region.NextId++,Name="Survey a fallen college",Kind="Survey",FactionId=Region.Factions[4].Id,SiteId=lost.SiteId,Reward=new(){{"medicine",2}}});
  Region.RandomState=random.State;Region.History=Region.History.OrderBy(h=>h.Year).ThenBy(h=>h.Tick).ThenBy(h=>h.Id).ToList();Chronicle("Discovery","The refuge charts a region with six factions and history-linked sites.",site:home.Id);ValidateRegion(d);
 }
 private void DispatchRelief(RegionTreaty treaty,Dictionary<string,int> cargo)
 {if(Region.Traders.Count>=24)return;var faction=Region.Factions.First(f=>f.Id==treaty.FactionId);if(cargo.Any(k=>faction.Reserves.GetValueOrDefault(k.Key)<k.Value))return;foreach(var item in cargo)faction.Reserves[item.Key]-=item.Value;Region.Traders.Add(new(){Id=Region.NextId++,FactionId=faction.Id,ArrivesAt=Tick+TicksPerHour*2,LeavesAt=Tick+TicksPerDay,Relief=true,Cargo=cargo});Chronicle("Diplomacy",faction.Name+" dispatched reserve-backed relief under "+treaty.Kind+".",faction.Id,Region.HomeSiteId);}
 private void AdvanceRegion(Definitions d)
 {
  EnsureRegion();if(!Region.Enabled)return;AdvanceExpeditions(d);AdvanceTraders(d);
  foreach(var entry in Danger.History.Where(h=>h.Tick>Region.ObservedDangerTick && h.Kind is "Rescue" or "Treatment" or "Raid" or "Recovered")){Chronicle(entry.Kind,entry.Text,actor:entry.ActorId,site:Region.HomeSiteId);Region.History.Last().Tick=entry.Tick;}Region.ObservedDangerTick=Danger.History.Select(h=>h.Tick).DefaultIfEmpty(Region.ObservedDangerTick).Max();
  foreach(var craft in Physical.Crafts.Where(c=>c.Tick>Region.ObservedCraftTick))Chronicle("Craft",craft.Name+" was made from "+craft.Material+" at quality "+craft.Quality+".",actor:craft.Maker,site:Region.HomeSiteId);Region.ObservedCraftTick=Physical.Crafts.Select(c=>c.Tick).DefaultIfEmpty(Region.ObservedCraftTick).Max();
  foreach(var treaty in Region.Treaties.Where(t=>t.Active&&t.Kind=="Mutual defense"&&Tick>=t.DueAt))if(Danger.Raid.Phase is "Warning" or "Fighting"){DispatchRelief(treaty,new(){{"medicine",2},{"arrows",4}});treaty.DueAt=Tick+TicksPerDay*3;}
  foreach(var body in Danger.Bodies.Values.Where(b=>b.Dead&&Colony.People.ContainsKey(b.EntityId)))if(Region.RecordedDeaths.Add(body.EntityId))Chronicle("Death",Find(body.EntityId)!.Name+" died: "+body.DeathCause+".",actor:body.EntityId,site:Region.HomeSiteId);
  long day=Tick/TicksPerDay;if(day<=Region.LastDay)return;Region.LastDay=day;
  foreach(var treaty in Region.Treaties.Where(t=>t.Active&&t.Kind=="Sanctuary"&&Tick>=t.DueAt)){if(Resources("meal").Total<10)DispatchRelief(treaty,new(){{"meal",6}});treaty.DueAt=Tick+TicksPerDay*7;}
  foreach(var faction in Region.Factions){var town=Region.Sites.First(s=>s.Kind=="Town"&&s.FactionId==faction.Id);int climate=Region.Tiles[town.Y*12+town.X].Climate;int production=climate is <5 or >38?2:5;production=RegionalSolarProduction(faction,production);faction.Reserves["grain"]=Math.Min(10000,faction.Reserves.GetValueOrDefault("grain")+production);int consumption=Math.Min(faction.Reserves["grain"],Math.Max(1,faction.Population/30));faction.Reserves["grain"]-=consumption;faction.Reserves["wood"]=Math.Min(10000,faction.Reserves.GetValueOrDefault("wood")+2);if(faction.Reserves["grain"]==0&&faction.Population>20)faction.Population--;if(faction.Grievance>40&&faction.Strength<200&&faction.Reserves["wood"]>=2&&faction.Reserves["grain"]>0){faction.Reserves["wood"]-=2;faction.Reserves["grain"]--;faction.Strength++;}
   if(day%7==0&&faction.Reserves["grain"]<3&&faction.Population>20){var receiving=Region.Factions.Where(f=>f.Id!=faction.Id&&f.Reserves.GetValueOrDefault("grain")>30&&f.Population<9999).OrderBy(f=>f.Id).FirstOrDefault();if(receiving!=null){faction.Population--;receiving.Population++;receiving.Reserves["grain"]--;Chronicle("Migration","Shortage moved a resident from "+faction.Name+" to "+receiving.Name+".",faction.Id,town.Id);}}faction.Objective=faction.Reserves["grain"]<15?"Seek food":faction.Grievance>40?"Protect claims":"Trade";}
  foreach(var quest in Region.Quests.Where(q=>q.Status=="Accepted"&&Tick>q.Deadline)){quest.Status="Failed";var f=Region.Factions.First(f=>f.Id==quest.FactionId);f.Trust=Math.Max(-100,f.Trust-5);Chronicle("Quest","Contract expired: "+quest.Name+".",f.Id,quest.SiteId,quest.ArtifactId);}
  foreach(var treaty in Region.Treaties.Where(t=>t.Active&&t.Payment>0&&Tick>t.DueAt)){treaty.Active=false;var f=Region.Factions.First(f=>f.Id==treaty.FactionId);f.Grievance=Math.Min(100,f.Grievance+10);f.Trust=Math.Max(-100,f.Trust-5);Chronicle("Diplomacy","Missed tribute ended an agreement with "+f.Name+".",f.Id);}
  if(day%3==0&&Region.Traders.Count<24&&!Region.Traders.Any(t=>t.State is "Traveling" or "Visiting")){var f=Region.Factions.Where(f=>TradeAccess(f.Id)&&f.Reserves.GetValueOrDefault("medicine")>=3&&f.Reserves.GetValueOrDefault("meal")>=6).OrderBy(f=>f.Id).FirstOrDefault();if(f!=null){f.Reserves["medicine"]-=3;f.Reserves["meal"]-=6;Region.Traders.Add(new(){Id=Region.NextId++,FactionId=f.Id,ArrivesAt=Tick+TicksPerHour*2,LeavesAt=Tick+TicksPerDay,Cargo=new(){{"medicine",3},{"meal",6}}});Chronicle("Caravan",f.Name+" dispatched a trader from its actual export reserves.",f.Id);}}
 }
}
public static class LivingWorldGenerator {public static World Create(Definitions d,int seed){var w=PhysicalWorldGenerator.Create(d,seed);w.EnableRegion(d);return w;}}
